import{_ as i,c as l,o as e,ag as t}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"故障排除","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1794112334000}'),s={name:"zh-CN/guide/troubleshooting.md"};function o(r,a,n,h,p,c){return e(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h1><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="应用无法启动" tabindex="-1">应用无法启动 <a class="header-anchor" href="#应用无法启动" aria-label="Permalink to &quot;应用无法启动&quot;">​</a></h3><p><strong>现象</strong>：Nicasa 启动失败或立刻崩溃</p><p><strong>解决办法</strong>：</p><ol><li>确认系统为 macOS 10.13 或更高版本</li><li>确认至少拥有 4GB 内存</li><li>重启你的 Mac</li><li>从 Mac App Store 重新安装 Nicasa</li><li>检查是否存在冲突的应用</li></ol><h3 id="截图无法使用" tabindex="-1">截图无法使用 <a class="header-anchor" href="#截图无法使用" aria-label="Permalink to &quot;截图无法使用&quot;">​</a></h3><p><strong>现象</strong>：截图功能不工作</p><p><strong>解决办法</strong>：</p><ol><li><strong>授予屏幕录制权限</strong>： <ul><li>进入 系统设置 &gt; 隐私与安全性 &gt; 屏幕录制</li><li>勾选 Nicasa 旁边的复选框</li><li>重启 Nicasa</li></ul></li><li>确认没有其他截图工具正在运行</li><li>尝试重启你的 Mac</li></ol><h3 id="chrome-扩展无法使用" tabindex="-1">Chrome 扩展无法使用 <a class="header-anchor" href="#chrome-扩展无法使用" aria-label="Permalink to &quot;Chrome 扩展无法使用&quot;">​</a></h3><p><strong>现象</strong>：扩展不显示或无法提取图片</p><p><strong>解决办法</strong>：</p><ol><li>确认扩展已在 Chrome 中启用</li><li>检查 Chrome 版本是否兼容</li><li>尝试刷新网页</li><li>重新安装扩展</li><li>清除浏览器缓存与 Cookie</li></ol><h3 id="图片无法加载" tabindex="-1">图片无法加载 <a class="header-anchor" href="#图片无法加载" aria-label="Permalink to &quot;图片无法加载&quot;">​</a></h3><p><strong>现象</strong>：缩略图不显示或图片打不开</p><p><strong>解决办法</strong>：</p><ol><li>检查图片文件的访问权限</li><li>确认图片文件未损坏</li><li>确认格式受支持（JPEG、PNG、GIF、BMP、TIFF、WebP）</li><li>尝试重新打开该文件夹</li><li>重启 Nicasa</li></ol><h3 id="性能缓慢" tabindex="-1">性能缓慢 <a class="header-anchor" href="#性能缓慢" aria-label="Permalink to &quot;性能缓慢&quot;">​</a></h3><p><strong>现象</strong>：应用卡顿或缩略图加载很慢</p><p><strong>解决办法</strong>：</p><ol><li>关闭其他占用内存较多的应用</li><li>确保有充足的可用内存（推荐 8GB）</li><li>在偏好设置中调小缩略图网格尺寸</li><li>清理应用缓存</li><li>重启你的 Mac</li></ol><h3 id="ai-编辑器无法使用" tabindex="-1">AI 编辑器无法使用 <a class="header-anchor" href="#ai-编辑器无法使用" aria-label="Permalink to &quot;AI 编辑器无法使用&quot;">​</a></h3><p><strong>现象</strong>：AI 编辑工具不可用或不工作</p><p><strong>解决办法</strong>：</p><ol><li>确认网络连接稳定（部分功能需要联网）</li><li>检查你的 Mac 是否满足最低要求</li><li>重启 Nicasa</li><li>更新到最新版本</li><li>如问题依旧，请联系支持</li></ol><h3 id="权限问题" tabindex="-1">权限问题 <a class="header-anchor" href="#权限问题" aria-label="Permalink to &quot;权限问题&quot;">​</a></h3><p><strong>现象</strong>：应用请求权限，或某些功能不可用</p><p><strong>解决办法</strong>：</p><ol><li><strong>屏幕录制</strong>：系统设置 &gt; 隐私与安全性 &gt; 屏幕录制</li><li><strong>辅助功能</strong>：系统设置 &gt; 隐私与安全性 &gt; 辅助功能（用于悬浮模式）</li><li><strong>文件与文件夹</strong>：系统设置 &gt; 隐私与安全性 &gt; 文件与文件夹</li><li>授予权限后重启 Nicasa</li></ol><h3 id="悬浮模式问题" tabindex="-1">悬浮模式问题 <a class="header-anchor" href="#悬浮模式问题" aria-label="Permalink to &quot;悬浮模式问题&quot;">​</a></h3><p><strong>现象</strong>：透明悬浮模式工作不正常</p><p><strong>解决办法</strong>：</p><ol><li>在系统设置中授予辅助功能权限</li><li>确认没有其他悬浮类工具正在运行</li><li>尝试关闭再重新开启悬浮模式</li><li>重启 Nicasa</li></ol><h2 id="错误提示" tabindex="-1">错误提示 <a class="header-anchor" href="#错误提示" aria-label="Permalink to &quot;错误提示&quot;">​</a></h2><h3 id="需要屏幕录制权限" tabindex="-1">“需要屏幕录制权限” <a class="header-anchor" href="#需要屏幕录制权限" aria-label="Permalink to &quot;“需要屏幕录制权限”&quot;">​</a></h3><p><strong>解决办法</strong>：按上文「截图无法使用」一节所述授予屏幕录制权限。</p><h3 id="无法加载图片" tabindex="-1">“无法加载图片” <a class="header-anchor" href="#无法加载图片" aria-label="Permalink to &quot;“无法加载图片”&quot;">​</a></h3><p><strong>可能原因</strong>：</p><ul><li>文件已损坏</li><li>格式不受支持</li><li>文件权限问题</li><li>文件过大</li></ul><p><strong>解决办法</strong>：</p><ol><li>尝试用「预览」打开该文件，确认它是否有效</li><li>转换为受支持的格式</li><li>检查文件权限</li><li>确认为合理的文件体积</li></ol><h3 id="扩展无响应" tabindex="-1">“扩展无响应” <a class="header-anchor" href="#扩展无响应" aria-label="Permalink to &quot;“扩展无响应”&quot;">​</a></h3><p><strong>解决办法</strong>：刷新网页后重试。如果反复出现，请重新安装扩展。</p><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><p>如果问题依然存在：</p><ol><li>查阅本故障排除指南</li><li>访问我们的<a href="/zh-CN/guide/faq.html">常见问题</a></li><li>在 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a> 上提交 issue</li><li>请附上你的 macOS 版本、Nicasa 版本以及复现问题的详细步骤</li></ol><h2 id="系统信息" tabindex="-1">系统信息 <a class="header-anchor" href="#系统信息" aria-label="Permalink to &quot;系统信息&quot;">​</a></h2><p>反馈问题时，请提供：</p><ul><li>macOS 版本（苹果菜单 &gt; 关于本机）</li><li>Nicasa 版本（Nicasa &gt; 关于 Nicasa）</li><li>Mac 机型与芯片（Apple 芯片或 Intel）</li><li>复现问题的步骤</li><li>任何错误提示</li></ul><p>这通常意味着图片文件已被移动或删除。请尝试重新打开该文件夹或选择其他目录。</p><h3 id="不支持的格式" tabindex="-1">“不支持的格式” <a class="header-anchor" href="#不支持的格式" aria-label="Permalink to &quot;“不支持的格式”&quot;">​</a></h3><p>无法识别该图片格式。请查看<a href="/zh-CN/guide/usage.html">支持的格式</a>列表，或将图片转换为兼容格式。</p><h3 id="内存不足" tabindex="-1">“内存不足” <a class="header-anchor" href="#内存不足" aria-label="Permalink to &quot;“内存不足”&quot;">​</a></h3><p>系统可用内存不足。请关闭其他应用，或升级你的内存。</p><h2 id="进阶故障排除" tabindex="-1">进阶故障排除 <a class="header-anchor" href="#进阶故障排除" aria-label="Permalink to &quot;进阶故障排除&quot;">​</a></h2><h3 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to &quot;查看日志&quot;">​</a></h3><p>访问应用日志：</p><ol><li>进入 帮助 &gt; 显示日志</li><li>或在以下位置查找日志： <ul><li>Windows：<code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS：<code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux：<code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="重置应用" tabindex="-1">重置应用 <a class="header-anchor" href="#重置应用" aria-label="Permalink to &quot;重置应用&quot;">​</a></h3><p>将所有设置恢复为默认值：</p><ol><li>关闭 Nicasa</li><li>删除应用数据文件夹</li><li>重启 Nicasa</li></ol><h3 id="命令行选项" tabindex="-1">命令行选项 <a class="header-anchor" href="#命令行选项" aria-label="Permalink to &quot;命令行选项&quot;">​</a></h3><p>面向进阶用户，Nicasa 支持命令行参数：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 启用详细日志</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 重置所有设置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 打开指定文件夹</span></span></code></pre></div><h2 id="获取更多帮助" tabindex="-1">获取更多帮助 <a class="header-anchor" href="#获取更多帮助" aria-label="Permalink to &quot;获取更多帮助&quot;">​</a></h2><p>如果这些办法都没能解决你的问题：</p><ol><li>查看我们的<a href="/zh-CN/guide/faq.html">常见问题</a></li><li>搜索已有的 <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">issues</a></li><li>新建 issue，并附上： <ul><li>你的操作系统与版本</li><li>Nicasa 版本</li><li>复现问题的步骤</li><li>任何错误提示或截图</li></ul></li></ol>`,68)])])}const u=i(s,[["render",o]]);export{g as __pageData,u as default};
